# Rahmenbedingungen internationaler Geschäftstätigkeit (Folien mit Mitschrift, Paul). Jeder Stichpunkt „fehlt vielleicht“ einzeln geprüft (13.11.2026).
# Fast alle Treffer sind Texterkennung bzw. Schreibfehler der handschriftlichen Mitschrift; der Inhalt steht auf der Lernseite.
DECKNAME[F] = {'vl': 'Folien'}
kein(F, 'vl/8', 'Unterstaatlicher')                     # Mitschrift-Rest („unter staatlicher Hand“): Merkantilismus steht in phase13
kein(F, 'vl/10', 'Irgendwannbessere', 'Kriegenden', 'Kran-Lkwe')   # Mitschrift-Reste; Containerisierung/Bretton Woods in phase4
kein(F, 'vl/12', 'Transportwegenicht', 'Elektronikkonsum')          # Mitschrift-Reste; Phase 5 vollständig in phase56
ok(F, 'vl/14', 'Enthopphing', 'Deriskina')               # Schreibfehler für Decoupling/Entkopplung, Derisking: stehen in phase56
kein(F, 'vl/18', 'Rückschau', 'Bislang', 'Präsentationsdauer')   # Gruppenauftrag (Präsentation), laut Folie „nur kurz angeschnitten“
kein(F, 'vl/23', 'Jedermans', 'Petrobas', 'Roebuck', 'Chevron', 'Mitsubishi', 'Telephone', 'Bethlehem', 'Sumitomo', 'Telecom', 'Richfield', 'Atlantic', 'Bristol-Myers')   # Firmennamen der Ranglisten-Tabelle; Aussage (Rohstoffe → Technik) steht in wertvollste
ok(F, 'vl/24', 'Thomotiv-Konzept', 'Tomotiv-Konzept')   # Texterkennung für „Lokomotiv-Konzept“: steht in wertvollste
ok(F, 'vl/28', 'Ländergrenzen')
ok(F, 'vl/39', 'Exporting', 'Producing', 'Zivilgesellschaft', 'Interessabündnis'); kein(F, 'vl/39', 'Demokratie-Gelaber')   # OPEC/BRICS stehen in opec
kein(F, 'vl/45', 'Gehalts'); kein(F, 'vl/54', 'Kapazitätist'); ok(F, 'vl/63', 'Lager-Bestand'); kein(F, 'vl/63', 'Unterschrieben')
ok(F, 'vl/76', 'Eisenindustrie'); kein(F, 'vl/82', 'Aufsichbrat'); kein(F, 'vl/94', 'Kleidug'); kein(F, 'vl/108', 'Ingeneursausbildung')
kein(F, 'vl/110', 'Technologieentwiklung'); ok(F, 'vl/119', 'Internationalization'); kein(F, 'vl/119', 'Lizensen', 'Geselge')
kein(F, 'vl/133', 'Nord-Korea'); kein(F, 'vl/145', 'Unterschiedefür'); kein(F, 'vl/157', 'Fspanne')
kein(F, 'vl/162', 'Stuhl-', 'Sitzf-')                   # Beschriftung der Schaubild-Kästen (Stuhlbeine, Sitzfläche)
kein(F, 'vl/175', 'Accomodating', 'Avoidoing')          # Schreibfehler der Folie; Accommodating/Avoiding stehen in konflikte
